import numpy as np


def _parts(x, enc, dec, s, n, seed):
    m, logvar = enc(x)
    eps = np.random.default_rng(seed).standard_normal(n)
    z = m + np.exp(0.5 * logvar) * eps
    d2 = ((np.asarray(x, dtype=float) - dec(z)) ** 2).sum(axis=1)
    log_px_z = -np.log(2 * np.pi * s * s) - d2 / (2 * s * s)
    log_pz = -0.5 * np.log(2 * np.pi) - z ** 2 / 2
    log_q = -0.5 * np.log(2 * np.pi) - logvar / 2 - eps ** 2 / 2
    return log_px_z, log_pz, log_q


def elbo_mc(x, enc, dec, s, n, seed):
    a, b, c = _parts(x, enc, dec, s, n, seed)
    return float(np.mean(a + b - c))


def two_terms(x, enc, dec, s, n, seed):
    a, b, c = _parts(x, enc, dec, s, n, seed)
    return float(np.mean(a)), float(np.mean(c - b))

